/// <summary>
/// Application Insights property for error message.
/// </summary>
public class OMGApplicationInsightsErrorMessageProperty extends SysApplicationInsightsProperty
{
}

Method.Source:
/// <summary>
/// Initializes a new instance of the <see cref="OMGApplicationInsightsErrorMessageProperty"/> class.
/// </summary>
/// <param name="_errorMessage">The error message.</param>
/// <returns>The new instance of the <see cref="OMGApplicationInsightsErrorMessageProperty"/> class.</returns>
public static OMGApplicationInsightsErrorMessageProperty newFromErrorMessage(str _errorMessage)
{
    return new OMGApplicationInsightsErrorMessageProperty(_errorMessage);
}
